'use strict';
// Original Six Men's Morris implementation. No flying; declared modern draw convention.
const SM_LINES=[[0,1,2],[2,3,4],[4,5,6],[6,7,0],[8,9,10],[10,11,12],[12,13,14],[14,15,8]];
const SM_NEIGHBORS=Array.from({length:16},(_,p)=>[(p&8)+((p+1)%8),(p&8)+((p+7)%8),...(p%2?[p<8?p+8:p-8]:[])]);
const smCopy=s=>JSON.parse(JSON.stringify(s));
const smKey=(b,seat)=>b.map(x=>x+1).join('')+':'+seat;
const smMills=(b,side)=>SM_LINES.filter(line=>line.every(p=>b[p]===side));
function smMoves(s,seat){
 if(s.phase==='over'||seat!==s.seat)return [];
 if(s.phase==='claim')return [{type:'claim_draw'},{type:'continue'}];
 const out=[],side=s.seat,b=s.board;
 if(s.history.filter(x=>x===smKey(b,side)).length>=3)out.push({type:'claim_draw'});
 const sources=s.reserve[side]>0?[-1]:b.flatMap((x,i)=>x===side?[i]:[]);
 for(const from of sources)for(const to of from<0?Array.from({length:16},(_,i)=>i):SM_NEIGHBORS[from].slice().sort((a,b)=>a-b)){
  if(b[to]!==-1)continue;const next=b.slice();next[to]=side;if(from>=0)next[from]=-1;
  const enemies=next.flatMap((x,i)=>x===1-side?[i]:[]);let targets=[-1];
  if(enemies.length&&smMills(next,side).some(line=>line.includes(to))){const protectedPoints=new Set(smMills(next,1-side).flat());const unprotected=enemies.filter(p=>!protectedPoints.has(p));targets=unprotected.length?unprotected:enemies;}
  for(const take of targets)out.push({type:from<0?'place':'slide',from,to,take});
 }
 return out;
}
function smScore(s,m){
 if(m.type==='claim_draw')return -100000;if(m.type==='continue')return 0;
 const b=s.board.slice(),side=s.seat;b[m.to]=side;if(m.from>=0)b[m.from]=-1;if(m.take>=0)b[m.take]=-1;
 let score=m.take>=0?-100:0;
 for(const line of SM_LINES){const mine=line.filter(p=>b[p]===side).length,theirs=line.filter(p=>b[p]===1-side).length,empty=line.filter(p=>b[p]===-1).length;if(mine===2&&empty===1)score-=8;if(theirs===2&&empty===1)score+=35;}
 score-=b.reduce((n,x,p)=>n+(x===side?SM_NEIGHBORS[p].filter(q=>b[q]===-1).length:0),0);
 if(b.filter(x=>x===1-side).length+s.reserve[1-side]<3)score-=10000;
 if(s.reserve[0]+s.reserve[1]===0&&!b.some((x,p)=>x===1-side&&SM_NEIGHBORS[p].some(q=>b[q]===-1)))score-=10000;
 return score;
}
function smRecommended(s,moves){if(!moves.length)return null;let best=moves[0],value=smScore(s,best);for(let i=1;i<moves.length;i++){const score=smScore(s,moves[i]);if(score<value){best=moves[i];value=score;}}return best;}
function smPayout(s,ctx){if(!ctx.pot)return {};const humans=ctx.players.filter(p=>p.kind==='human'&&p.active!==false),winner=s.winner>=0?ctx.players[s.winner]:null,receivers=winner&&winner.kind==='human'&&winner.active!==false?[winner]:humans,out={};humans.forEach(p=>out[p.id]=0);receivers.forEach((p,i)=>out[p.id]=Math.floor(ctx.pot/receivers.length)+(i<ctx.pot%receivers.length?1:0));return out;}
function smResult(s,ctx){return {state:s,turn:s.phase==='over'?null:[ctx.players[s.seat].id],...(s.phase==='over'?{payouts:smPayout(s,ctx)}:{})};}
const game={
 newMatch(ctx){const state={board:Array(16).fill(-1),reserve:[6,6],seat:0,phase:'play',resume:-1,quiet:0,history:['0000000000000000:0'],winner:-1,reason:'playing'};return smResult(state,ctx);},
 applyMove(state,id,m,ctx){
  if(state.phase==='over')throw new InvalidMove('The game has ended.');
  const seat=ctx.players.findIndex(p=>p.id===id);if(seat!==state.seat)throw new InvalidMove('Wait for your turn.');
  if(!m||typeof m!=='object'||Array.isArray(m))throw new InvalidMove('Choose a listed legal move.');
  const special=m.type==='claim_draw'||m.type==='continue',keys=Object.keys(m).sort();
  if(special?keys.join(',')!=='type':keys.join(',')!=='from,take,to,type'||!['place','slide'].includes(m.type)||!Number.isInteger(m.from)||!Number.isInteger(m.to)||!Number.isInteger(m.take)||m.from< -1||m.from>15||m.to<0||m.to>15||m.take< -1||m.take>15)throw new InvalidMove('Choose a listed legal move.');
  const legal=smMoves(state,seat),found=legal.find(a=>a.type===m.type&&(special||a.from===m.from&&a.to===m.to&&a.take===m.take));if(!found)throw new InvalidMove('Choose a listed legal move.');
  const s=smCopy(state);
  if(m.type==='claim_draw'){s.phase='over';s.reason='claimed';s.resume=-1;return smResult(s,ctx);}
  if(m.type==='continue'){s.phase='play';s.seat=s.resume;s.resume=-1;return smResult(s,ctx);}
  s.board[m.to]=seat;if(m.from<0)s.reserve[seat]--;else s.board[m.from]=-1;if(m.take>=0)s.board[m.take]=-1;
  s.seat=1-seat;s.quiet=m.from<0||m.take>=0?0:s.quiet+1;
  const position=smKey(s.board,s.seat);s.history=s.quiet===0?[position]:s.history.concat(position);
  if(s.board.filter(x=>x===s.seat).length+s.reserve[s.seat]<3){s.phase='over';s.winner=seat;s.reason='material';}
  else if(s.reserve[0]+s.reserve[1]===0&&!s.board.some((x,p)=>x===s.seat&&SM_NEIGHBORS[p].some(q=>s.board[q]===-1))){s.phase='over';s.winner=seat;s.reason='blocked';}
  else{const repetitions=s.history.filter(x=>x===position).length;if(repetitions>=5){s.phase='over';s.reason='repetition';}else if(s.quiet>=100){s.phase='over';s.reason='quiet';}else if(repetitions>=3){s.phase='claim';s.resume=s.seat;s.seat=seat;}}
  return smResult(s,ctx);
 },
 viewFor(s,id,ctx){const seat=ctx.players.findIndex(p=>p.id===id),v={};for(const k of ['board','reserve','seat','phase','quiet','winner','reason'])v[k]=smCopy(s[k]);v.counts=[s.board.filter(x=>x===0).length,s.board.filter(x=>x===1).length];v.mills=[smMills(s.board,0),smMills(s.board,1)];v.repetitions=s.history.filter(x=>x===s.history[s.history.length-1]).length;v.moves=smMoves(s,seat);v.recommended=smRecommended(s,v.moves);return v;},
 computerMove(s,id,ctx){return smRecommended(s,smMoves(s,ctx.players.findIndex(p=>p.id===id)));},
 randomMove(s,id,ctx){const moves=smMoves(s,ctx.players.findIndex(p=>p.id===id)),best=Math.min(...moves.map(m=>smScore(s,m))),choices=moves.filter(m=>smScore(s,m)===best);return choices[Math.floor(ctx.random()*choices.length)];}
};

